__NUXT_JSONP__("/inclusion/eventos/el_cuidado_de_la_primera_infancia_requiere_corresponsabilidad", (function(a,b,c,d,e){return {data:[{post:{slug:"el_cuidado_de_la_primera_infancia_requiere_corresponsabilidad",title:"El cuidado de la primera infancia requiere corresponsabilidad",date:"2025-03-04T19:54:23.230Z",img:"https:\u002F\u002Fucarecdn.com\u002F31d881bb-8089-4d39-b0e6-e4ed4e961deb\u002F","img-alt":"Mónica Corona, Ethos",autor:"Ethos",category:"inclusion",extracto:"Para que el cuidado de la primera infancia deje de depender casi exclusivamente de las mujeres, se requiere articular políticas entre el gobierno, las empresas, la comunidad y las familias, consideró Mónica Corona, directora de Inclusión y Desarrollo Sostenible en Ethos, en un foro organizado por el Senado de la República.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Los cuidados y educación en la primera infancia son fundamentales para el desarrollo y bienestar infantil. Sin embargo, actualmente la organización de ese cuidado, y de muchos otros, recae de manera desproporcionada sobre las mujeres. Esto afecta su salud mental, emocional, económica y su calidad de vida, lo cual tiene repercusiones también en las infancias. En este contexto, se requiere responsabilidad compartida en el cuidado de niñas y niños."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Así lo destacó Mónica Corona, directora de Inclusión y Desarrollo Sostenible en Ethos, al hablar sobre la corresponsabilidad de los cuidados de la primera infancia, dentro del Foro “Prioridades de atención de la primera infancia 2024-2030”, organizado por la senadora Alma Anahí González Hernández y el Early Institute."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Tal como están concebidos y distribuidos actualmente, los cuidados de la primera infancia dependen casi exclusivamente de las mujeres y de los arreglos familiares. Propongo que retomemos la definición inicial del cuidado como una manera de procurar la vida para todas las personas”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Mónica Corona explicó que se requiere colocar el derecho a cuidar y ser cuidado en el centro de nuestras políticas públicas, articular políticas entre el gobierno, las empresas, la comunidad y las familias, tanto hombres como mujeres. “No significa que las familias dejen de cuidar, sino que hay otros actores que asumen un rol activo en su organización”, precisó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, señaló que es deseable ampliar la cobertura de los servicios existentes de guarderías, educación inicial y centros de cuidado, con normas claras de profesionalización, y que sean gratuitos o subsidiados; y la formalización del empleo en el sector de cuidados con capacitación, mejores salarios, protección social, entre otras medidas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“La corresponsabilidad en el cuidado tiene efectos positivos sobre la igualdad de género, la calidad de vida de las mujeres, el desarrollo infantil, las oportunidades laborales para las mujeres, la generación de empleos en el sector de cuidados, el involucramiento y disfrute de los hombres en la crianza, la ruptura de ciclos de pobreza generacionales, y el fortalecimiento del tejido social”, expresó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En esta mesa de trabajo, moderada por Renata Díaz Barreiro, del Early Institute, participaron también Sunny Arely Villa Juárez, investigadora del Centro de Investigación Económica y Presupuestaria y Martha Merlo Huerta, Oficial Nacional de Política Social de UNICEF."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fel_cuidado_de_la_primera_infancia_requiere_corresponsabilidad",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-04-23T06:21:15.372Z")));